import{_ as n,o as s,c as a,ah as r}from"./chunks/framework.e_ysbW9u.js";const l="/projects/ROSPug/en/latest/assets/image2.B_t6n1eL.png",c="/projects/ROSPug/en/latest/assets/image3.DlsRdw5n.png",d="/projects/ROSPug/en/latest/assets/image4.3H37yrkL.png",g="/projects/ROSPug/en/latest/assets/image5.JFUyu0X8.png",h="/projects/ROSPug/en/latest/assets/image6.DJt_i_fO.png",p="/projects/ROSPug/en/latest/assets/image7.B4BeK8mq.png",m="data:image/png;base64,",u="data:image/png;base64,",A="data:image/png;base64,",f="data:image/png;base64,",y="data:image/png;base64,",b="data:image/png;base64,",w="/projects/ROSPug/en/latest/assets/image14.DQRZGR3p.png",v="data:image/png;base64,",k="/projects/ROSPug/en/latest/assets/image16.exXuxJfL.png",R="data:image/png;base64,",x="data:image/png;base64,",C="data:image/png;base64,",I="data:image/png;base64,",S="data:image/png;base64,",z="data:image/png;base64,",B="data:image/png;base64,",T="/projects/ROSPug/en/latest/assets/image2.BfjVCPX_.png",E="/projects/ROSPug/en/latest/assets/image3.CnIT5usW.png",U="/projects/ROSPug/en/latest/assets/image4.CYKLRSI_.png",Y="/projects/ROSPug/en/latest/assets/image5.y68lgULc.png",Q="/projects/ROSPug/en/latest/assets/image8.GIr_RJwc.png",F="/projects/ROSPug/en/latest/assets/image9.5lnxcWf4.png",P="/projects/ROSPug/en/latest/assets/image10.B0r1LptT.png",q="/projects/ROSPug/en/latest/assets/image11.DnGr3gWF.png",D="/projects/ROSPug/en/latest/assets/image12.CSaYo4W9.png",j="/projects/ROSPug/en/latest/assets/image13.90gGaMCt.png",O="/projects/ROSPug/en/latest/assets/image14.DMHxA1wq.png",G="/projects/ROSPug/en/latest/assets/image15.TOscXRLs.png",M="/projects/ROSPug/en/latest/assets/image16.Dqd4xkfQ.png",N="/projects/ROSPug/en/latest/assets/image17.BHgvoAxr.png",V="/projects/ROSPug/en/latest/assets/image2.dSNJNGGo.png",H="/projects/ROSPug/en/latest/assets/image3.Cs9DcV6d.png",X="/projects/ROSPug/en/latest/assets/image3.CnIT5usW.png",L="/projects/ROSPug/en/latest/assets/image5.Dq5QJvXD.png",J="/projects/ROSPug/en/latest/assets/image2.DozDxarH.png",W="/projects/ROSPug/en/latest/assets/image3.aBLfgEOQ.png",e="/projects/ROSPug/en/latest/assets/image2.BfjVCPX_.png",o="data:image/png;base64,",Z="/projects/ROSPug/en/latest/assets/image8.CkZfMBP-.png",K="/projects/ROSPug/en/latest/assets/image9.Czc9B_VR.png",_="/projects/ROSPug/en/latest/assets/image10.BVPgg8rz.png",$="/projects/ROSPug/en/latest/assets/image11.ClWPNMBP.png",tt="data:image/png;base64,",et="/projects/ROSPug/en/latest/assets/image13.D8wC7DT8.png",ot="/projects/ROSPug/en/latest/assets/image14.Di_0vWMN.png",i="data:image/png;base64,",it="/projects/ROSPug/en/latest/assets/image23.QYy7EiT5.png",nt="/projects/ROSPug/en/latest/assets/image24.BWoChIa8.png",st="/projects/ROSPug/en/latest/assets/image25.Bt_f5cdn.png",at="/projects/ROSPug/en/latest/assets/image26.U9rLD43Q.png",rt="data:image/png;base64,",lt="/projects/ROSPug/en/latest/assets/image28.CHtj5fRS.png",ct="/projects/ROSPug/en/latest/assets/image29.DOtCLR0m.png",dt="/projects/ROSPug/en/latest/assets/image30.DwuA8kEE.png",gt="/projects/ROSPug/en/latest/assets/image31.CT7ghRsd.png",ht="/projects/ROSPug/en/latest/assets/image33.CV4MGn8w.png",pt="/projects/ROSPug/en/latest/assets/image35.Bk8r_2k-.png",mt="/projects/ROSPug/en/latest/assets/image38.U33umHKb.png",ut="/projects/ROSPug/en/latest/assets/image40.B0AI9Jq1.png",At="/projects/ROSPug/en/latest/assets/image41.BLAIo_Ye.png",Ct=JSON.parse('{"title":"6. Simulation Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6.Simulation_Course.md","filePath":"docs/6.Simulation_Course.md"}'),ft={name:"docs/6.Simulation_Course.md"};function yt(bt,t,wt,vt,kt,Rt){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_6-simulation-course" tabindex="-1">6. Simulation Course <a class="header-anchor" href="#_6-simulation-course" aria-label="Permalink to &quot;6. Simulation Course&quot;">​</a></h1><h2 id="_6-1-urdf-model-introduction" tabindex="-1">6.1 URDF Model Introduction <a class="header-anchor" href="#_6-1-urdf-model-introduction" aria-label="Permalink to &quot;6.1 URDF Model Introduction&quot;">​</a></h2><p>The Unified Robot Description Format (<strong>URDF</strong>) is an <strong>XML</strong> file format widely used in <strong>ROS</strong> (<strong>Robot Operating System</strong>) to comprehensively describe all components of a robot.</p><p>Robots are typically composed of multiple links and joints. A link is defined as a rigid object with certain physical properties, while a joint connects two links and constrains their relative motion.</p><p>By connecting links with joints and imposing motion restrictions, a kinematic model is formed. The <strong>URDF</strong> file specifies the relationships between joints and links, their inertial properties, geometric characteristics, and collision models.</p><h3 id="_6-1-1-comparison-between-xacro-and-urdf-model" tabindex="-1">6.1.1 Comparison between Xacro and *URDF Model <a class="header-anchor" href="#_6-1-1-comparison-between-xacro-and-urdf-model" aria-label="Permalink to &quot;6.1.1 Comparison between Xacro and *URDF Model&quot;">​</a></h3><p>The <strong>URDF</strong> model serves as a description file for simple robot models, offering a clear and easily understandable structure. However, when it comes to describing complex robot structures, using <strong>URDF</strong> alone can result in lengthy and unclear descriptions.</p><p>To address this limitation, the <strong>xacro</strong> model extends the capabilities of <strong>URDF</strong> while maintaining its core features. The <strong>xacro</strong> format provides a more advanced approach to describe robot structures. It greatly improves code reusability and helps avoid excessive description length.</p><p>For instance, when describing the two legs of a humanoid robot, the <strong>URDF</strong> model would require separate descriptions for each leg. On the other hand, the <strong>xacro</strong> model allows for describing a single leg and reusing that description for the other leg, resulting in a more concise and efficient representation.</p><h3 id="_6-1-2-basic-syntax-of-urdf-model" tabindex="-1">6.1.2 Basic Syntax of URDF Model <a class="header-anchor" href="#_6-1-2-basic-syntax-of-urdf-model" aria-label="Permalink to &quot;6.1.2 Basic Syntax of URDF Model&quot;">​</a></h3><ul><li><strong>XML Basic Syntax</strong></li></ul><p>(1) Elements:</p><p>An element can be defined as desired using the following formula:</p><p><code>&lt;element&gt;</code></p><p><code>&lt;/element&gt;</code></p><p>(2) Properties:</p><p>Properties are included within elements to define characteristics and parameters. Please refer to the following formula to define an element with properties:</p><p><code>&lt;element</code></p><p><code>property_1=&quot;property value1&quot;</code></p><p><code>property_2=&quot;property value2&quot;&gt;</code></p><p><code>&lt;/element&gt;</code></p><p>(3) Comments:</p><p>Comments have no impact on the definition of other properties and elements. Please use the following formula to define a comment:</p><p><code>&lt;!-- comment content --&gt;</code></p><ul><li><strong>Link</strong></li></ul><p>The <code>Link</code> element describes the visual and physical properties of the robot&#39;s rigid component. The following tags are commonly used to define the motion of a link:</p><img loading="lazy" height="113" width="506" src="'+l+'" class="common_img"><p><code>&lt;visual&gt;</code>: Describe the appearance of the link, such as size, color and shape.</p><p><code>&lt;inertial&gt;</code>: Describe the inertia parameters of the link, which will be used in dynamics calculation.</p><p><code>&lt;collision&gt;</code>: Describe the collision inertia property of the link.</p><p>Each tag contains the corresponding child tag. The functions of the tags are listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Tag</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">origin</td><td style="text-align:center;">Describe the pose of the link. It contains two parameters, including <code>xyz</code> and <code>rpy</code>. <code>Xyz</code> describes the pose of the link in the simulated map. <code>Rpy</code> describes the pose of the link in the simulated map.</td></tr><tr><td style="text-align:center;">mass</td><td style="text-align:center;">Describe the mass of the link</td></tr><tr><td style="text-align:center;">inertia</td><td style="text-align:center;">Describe the inertia of the link. As the inertia matrix is symmetrical, these six parameters need to be input, <code>ixx</code>, <code>ixy</code>, <code>ixz</code>, <code>iyy</code>, <code>iyz</code> and <code>izz</code>, as properties. These parameters can be calculated.</td></tr><tr><td style="text-align:center;">geometry</td><td style="text-align:center;">Describe the shape of the link. It uses <code>mesh</code> parameter to load texture file, and employs <code>filename</code> parameters to load the path for texture file. It has three child tags, namely <code>box</code>, <code>cylinder</code> and <code>sphere</code>.</td></tr><tr><td style="text-align:center;">material</td><td style="text-align:center;">Describe the material of the link. The parameter <code>name</code> is the required field. The tag <code>color</code> can be used to change the color and transparency of the link.</td></tr></tbody></table><p id="6_1_2_3"></p><ul><li><strong>Joint</strong></li></ul><p>The <strong>&quot;Joint&quot;</strong> tag describes the kinematic and dynamic properties of the robot&#39;s joints, including the joint&#39;s range of motion, target positions, and speed limitations. In terms of motion style, joints can be categorized into six types.</p><img loading="lazy" height="345" width="510" src="'+c+'" class="common_img"><p>The following tags will be used to write joint motion.</p><img loading="lazy" height="153" width="296" src="'+d+'" class="common_img"><p>(1) <code>&lt;parent_link&gt;</code>: Parent link</p><p>(2) <code>&lt;child_link&gt;</code>: Child link</p><p>(3) <code>&lt;calibration&gt;</code>: Calibrate the joint angle</p><p>(4) <code>&lt;dynamics&gt;</code>: Describes some physical properties of motion</p><p>(5) <code>&lt;limit&gt;</code>: Describes some limitations of the motion</p><p>The function of each tag is listed below. Each tag involves one or several child tags.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Tag</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">origin</td><td style="text-align:center;">Describe the pose of the parent link. It involves two parameters, including xyz and rpy. Both xyz and rpy describe the pose of the link in simulated map.</td></tr><tr><td style="text-align:center;">axis</td><td style="text-align:center;">Control the child link to rotate around any axis of the parent link.</td></tr><tr><td style="text-align:center;">limit</td><td style="text-align:center;">The motion of the child link is constrained using the lower and upper properties, which define the limits of rotation for the child link. The effort properties restrict the allowable force range applied during rotation (values: positive and negative; units: <strong>N</strong>). The velocity properties confine the rotational speed, measured in meters per second (<strong>m/s</strong>).</td></tr><tr><td style="text-align:center;">mimic</td><td style="text-align:center;">Describe the relationship between joints.</td></tr><tr><td style="text-align:center;">safety_controller</td><td style="text-align:center;">Describes the parameters of the safety controller used for protecting the joint motion of the robot.</td></tr></tbody></table><ul><li><strong>Robot Tag</strong></li></ul><p>The complete top tags of a robot, including the <code>&lt;link&gt;</code> and <code>&lt;joint&gt;</code> tags, must be enclosed within the <code>&lt;robot&gt;</code> tag. The format is as follows:</p><img loading="lazy" height="152" width="242" src="'+g+'" class="common_img"><ul><li><strong>Gazebo Tag</strong></li></ul><p>This tag is used in conjunction with the <strong>Gazebo</strong> simulator. Within this tag, you can define simulation parameters and import <strong>Gazebo</strong> plugins, as well as specify <strong>Gazebo</strong>&#39;s physical properties, and more.</p><img loading="lazy" height="71" width="299" src="'+h+'" class="common_img"><ul><li><strong>Write Simple URDF Model</strong></li></ul><img loading="lazy" height="1391" width="972" src="'+p+'" class="common_img"><p>(1) Name the model of the robot To start writing the <strong>URDF</strong> model, we need to set the name of the robot following this format: <code>&lt;robot name=&quot;robot model name&quot;&gt;</code>. Lastly, input <code>&lt;/robot&gt;</code> at the end to represent that the model is written successfully.</p><img loading="lazy" height="42" width="192" src="'+m+'" class="common_img"><img loading="lazy" height="19" width="75" src="'+u+'" class="common_img"><p>(2) Set Links</p><p>① To write the first link and use indentation to indicate that it is part of the currently set model. Set the name of the link using the following format: &quot;<code>&lt;link name=&quot;link name&quot;&gt;</code>&quot;. Finally, conclude with <code>&lt;/link&gt;</code> to indicate the successful completion of the link definition.</p><img loading="lazy" height="22" width="189" src="'+A+'" class="common_img"><img loading="lazy" height="22" width="82" src="'+f+'" class="common_img"><p>② Write the link description and use indentation to indicate that it is part of the currently set link, and conclude with <code>&lt;/visual&gt;</code>.</p><img loading="lazy" height="24" width="82" src="'+y+'" class="common_img"><img loading="lazy" height="28" width="136" src="'+b+'" class="common_img"><p>③ The <strong>&quot;geometry&quot;</strong> tag is employed to define the shape of a link. Once the description is complete, include <code>&lt;/geometry&gt;</code>. Within the <strong>&quot;geometry&quot;</strong> tag, indentation is used to specify the detailed description of the link&#39;s shape. The following example demonstrates a link with a cylindrical shape: <code>&lt;cylinder length=&quot;0.01&quot; radius=&quot;0.2&quot;/&gt;</code>. In this instance, <code>length=&quot;0.01&quot;</code> signifies a length of 0.01 meters for the link, while <code>radius=&quot;0.2&quot;</code> denotes a radius of 0.2 meters, resulting in a cylindrical shape.</p><img loading="lazy" height="73" width="384" src="'+w+'" class="common_img"><p>④ The <strong>&quot;origin&quot;</strong> tag is utilized to specify the position of a link, with indentation used to indicate the detailed description of the link&#39;s position. The following example demonstrates the position of a link: <code>&lt;origin rpy=&quot;0 0 0&quot; xyz=&quot;0 0 0&quot; /&gt;</code>. In this example, <code>rpy</code> represents the roll, pitch, and yaw angles of the link, while <code>xyz</code> represents the coordinates of the link&#39;s position. This particular example indicates that the link is positioned at the origin of the coordinate system.</p><img loading="lazy" height="17" width="311" src="'+v+'" class="common_img"><p>⑤ The <strong>&quot;material&quot;</strong> tag is used to define the visual appearance of a link, with indentation used to specify the detailed description of the link&#39;s color. To start describing the color, include <code>&lt;material&gt;</code>, and end with <code>&lt;/material&gt;</code> when the description is complete. The following example demonstrates setting a link color to yellow: <code>&lt;color rgba=&quot;1 1 0 1&quot; /&gt;</code>. In this example, <code>rgba=&quot;1 1 0 1&quot;</code> represents the color threshold for achieving a yellow color.</p><img loading="lazy" height="61" width="314" src="'+k+'" class="common_img"><p>(3) Set Joint</p><p>① To write the first joint, use indentation to indicate that the joint belongs to the current model being set. Then, specify the name and type of the joint as follows: <code>&lt;joint name=&quot;joint name&quot; type=&quot;joint type&quot;&gt;</code>. Finally, include <code>&lt;/joint&gt;</code> to indicate the completion of the joint definition.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>To learn about the type of the joint, please refer to <a href="#6_1_2_3">Joint</a>.</p></section><img loading="lazy" height="20" width="391" src="'+R+'" class="common_img"><img loading="lazy" height="19" width="121" src="'+x+'" class="common_img"><p>② Write the description section for the connection between the link and the joint. Use indentation to indicate that it is part of the currently defined joint. The <code>parent</code> parameter and <code>child</code> parameter should be set using the following format: <code>&lt;parent link=&quot;parent link&quot;/&gt;</code>, and <code>&lt;child link=&quot;child link&quot; /&gt;</code>. With the parent link serving as the pivot, the joint rotates the child link.</p><img loading="lazy" height="43" width="297" src="'+C+'" class="common_img"><p>③ <code>origin</code> describes the position of the joint using indentation. This example describes the position of the joint: <code>&lt;origin xyz=&quot;0 0 0.1&quot; /&gt;</code>. <code>xyz</code> is the coordinate of the joint.</p><img loading="lazy" height="22" width="240" src="'+I+'" class="common_img"><p>④ <code>axis</code> describes the position of the joint adopting indentation. <code>&lt;axis xyz=&quot;0 0 1&quot; /&gt;</code> describes one posture of a joint. <code>Xyz</code> specifies the pose of the joint.</p><img loading="lazy" height="24" width="241" src="'+S+'" class="common_img"><p>⑤ <code>limit</code> imposes restrictions on the joint using indentation. The <strong>&quot;limit&quot;</strong> tag is used to restrict the motion of a joint, with indentation indicating the specific description of the joint angle limitations. The following example describes a joint with a maximum force limit of 300 Newtons, an upper limit of 3.14 radians, and a lower limit of -3.14 radians. The settings are defined as follows: <code>effort=&quot;joint force (N)&quot;, velocity=&quot;joint motion speed&quot;, lower=&quot;lower limit in radians&quot;, upper=&quot;upper limit in radians&quot;</code>.</p><img loading="lazy" height="16" width="516" src="'+z+'" class="common_img"><p>⑥ <code>dynamics</code> describes the dynamics of the joint using indentation. <code>&lt;dynamics damping=&quot;50&quot; friction=&quot;1&quot; /&gt;</code> describes dynamics parameters of a joint.</p><img loading="lazy" height="20" width="310" src="'+B+'" class="common_img"><h2 id="_6-2-rospug-urdf-model-introduction" tabindex="-1">6.2 ROSPug URDF Model Introduction <a class="header-anchor" href="#_6-2-rospug-urdf-model-introduction" aria-label="Permalink to &quot;6.2 ROSPug URDF Model Introduction&quot;">​</a></h2><p>(1) Start the robot dog, and access the robot system desktop using <strong>NoMachine</strong>.</p><p>(2) Double-click <img loading="lazy" height="59" width="69" src="'+T+'"> to initiate the command-line terminal.</p><p>(3) Execute the command below to start <strong>Gazebo</strong> simulation. When the terminal prints the content illustrated as the picture below, it means that the <strong>Gazebo</strong> model is enabled successfully.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch pug_description gazebo.launch</span></span></code></pre></div><img loading="lazy" height="592" width="1447" src="'+E+'" class="common_img"><p>(5) Simply click on the <strong>Gazebo</strong> window to visualize the model. For ease of comprehension, envision the <strong>ROSPug</strong> robot model comprising 4 mechanical legs, controllers, a camera, and a <strong>LiDAR</strong>. To optimize the simulation&#39;s fluidity, the model has been moderately streamlined, introducing minor distinctions from the actual robot.</p><img loading="lazy" height="678" width="1273" src="'+U+'" class="common_img"><p>(6) Each leg consists of 3 joints and 4 links, with one servo corresponding to each joint.</p><img loading="lazy" height="694" width="1183" src="'+Y+'" class="common_img"><h3 id="_6-2-1-open-urdf-model-file" tabindex="-1">6.2.1 Open <strong>URDF</strong> Model File <a class="header-anchor" href="#_6-2-1-open-urdf-model-file" aria-label="Permalink to &quot;6.2.1 Open **URDF** Model File&quot;">​</a></h3><p>(1) Open the terminal and enter the following command to navigate to the folder storing the <strong>URDF</strong> mode.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd pug/src/pug_description/urdf</span></span></code></pre></div><p>(2) Take <code>pug.urdf.xacro</code> as example. Execute the command below and open <strong>URDF</strong> model using <strong>vim</strong> editor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim pug.urdf.xacro</span></span></code></pre></div><p>(3) When the terminal prints the following content, it indicates that the <strong>ROSPug</strong> robot <strong>URDF</strong> model file has been opened successfully:</p><img loading="lazy" height="472" width="726" src="'+Q+'" class="common_img"><h3 id="_6-2-2-analysis-of-urdf-model" tabindex="-1">6.2.2 Analysis of URDF Model <a class="header-anchor" href="#_6-2-2-analysis-of-urdf-model" aria-label="Permalink to &quot;6.2.2 Analysis of  URDF Model&quot;">​</a></h3><ul><li><strong>URDF Model Structure</strong></li></ul><p>The <strong>URDF</strong> model file for <strong>ROSPug</strong> consists of three files: <code>&#39;pug.urdf.xacro,&#39; &#39;pug.gazebo.xacro,&#39;</code> and <code>&#39;pug.transmission.xacro.&#39;</code> Among them, <code>&#39;pug.urdf.xacro&#39;</code> serves as the main <strong>URDF</strong> file for the entire robot. It incorporates the other two <strong>xacro</strong> files using <code>&#39;include,&#39;</code> bringing together various files within the <strong>URDF</strong> that define the complete mechanical structure, dynamics, simulation, and other information for <strong>ROSPug</strong>. The organization of files through <code>&#39;include&#39;</code> and macro references helps compartmentalize functional modules, making it easier to read and maintain, ultimately resulting in a comprehensive <strong>URDF</strong> model file.</p><img loading="lazy" height="362" width="749" src="'+F+'" class="common_img"><ul><li><strong>Analysis of pug.urdf.xacro File</strong></li></ul><p>It outlines the fundamental structure of the robot, encompassing the chassis, joints, connections, and more. This file also incorporates various macro and attribute definitions, enabling their repeated use in the code to simplify and prevent redundancy. Given the extensive code, it will be divided into three parts here for illustration, focusing mainly on the following sections:</p><p>(1) Model and Attribute Definition</p><p>① The <strong>&quot;robot&quot;</strong> tag establishes the name of the robot model as <code>&quot;</code>puppy<code>,&quot;</code> while the <strong>&quot;property&quot;</strong> tag defines certain attribute values, representing maximum torque and joint maximum velocity.</p><p>② The <strong>&quot;include&quot;</strong> statement brings in two files: <code>&#39;pug.transmission.xacro&#39;</code> and <code>&#39;pug.gazebo.xacro&#39;</code>. These files encompass the robot&#39;s transmission system and various attributes in the <strong>Gazebo</strong> simulation environment.</p><img loading="lazy" height="229" width="652" src="'+P+'" class="common_img"><p>(2) Definition of Link</p><p>The <code>Link</code> element represents a rigid body within the robot model, and it can include information such as inertia, visualization details, collision data, and more. Below is an example code for a <code>Link</code> element, encompassing inertia, visualization, and collision information:</p><img loading="lazy" height="484" width="764" src="'+q+'" class="common_img"><p>(3) Definition of Joint</p><p>The <code>Joint</code> element signifies a joint within the robot model, connecting two <code>Links</code> and defining their relative motion. Below is an example code for a <code>Joint</code> element, encompassing information such as the joint type, connected <code>Links</code>, the direction of the joint axis, and joint constraints:</p><img loading="lazy" height="174" width="703" src="'+D+'" class="common_img"><ul><li><strong>Analysis of pug.gazebo.xacro File</strong></li></ul><p>Primarily employed for crafting robot models within the <strong>Gazebo</strong> simulator, it outlines the physical characteristics, joint control, sensor data, and other details of various components of a robot. This facilitates simulation, control, and testing in the <strong>Gazebo</strong> environment. Given the extensive code, it will be presented in three parts for illustration, focusing mainly on the following sections:</p><p>(1) Definition of Gazebo Plugin</p><p>This section defines a <strong>Gazebo</strong> plugin, <code>&#39;gazebo_ros_control,&#39;</code> used for implementing robot control. The specific implementation of this plugin is provided by the <code>&#39;libgazebo_ros_control.so&#39;</code> library. It also configures <strong>Gazebo</strong> simulation types and namespaces.</p><img loading="lazy" height="161" width="616" src="'+j+'" class="common_img"><p>(2) Macro Definition</p><p>This tag defines several <strong>Xacro</strong> macros for conveniently configuring the color and physical properties of various <code>Links</code> within the robot model. The <code>&#39;model_color&#39;</code> macro is used for setting the color of a <code>Link</code>, while the <code>&#39;link_setup_block&#39;</code> macro is employed for configuring the physical properties of a <code>Link</code>.</p><img loading="lazy" height="406" width="531" src="'+O+'" class="common_img"><p>(3) Use Macros</p><p>Utilize the mentioned macros to configure the color and physical properties of various <code>Links</code> within the robot model. Specifically, the <code>&#39;gazebo_coxa,&#39; &#39;gazebo_thigh,&#39;</code> and <code>&#39;gazebo_calf&#39;</code> macros are employed to set the physical properties of the hip, thigh, and calf, respectively. These macros utilize the <code>&#39;gazebo&#39;</code> tag to configure the physical properties of the <code>Link</code>, such as friction coefficient, spring stiffness, and more.</p><img loading="lazy" height="271" width="339" src="'+G+'" class="common_img"><ul><li><strong>Analysis of pug.transmissions.xacro File</strong></li></ul><p>This <code>&#39;transmissions.xacro&#39;</code> file defines the transmission system within the robot model, specifying how the various joints interact with the motors. During runtime, <strong>ROS</strong> translates the <code>&#39;transmissions.xacro&#39;</code> file into the transmission system within the robot model. It primarily consists of the following two sections:</p><p>(1) Xacro Macro Definition</p><p><code>\\&lt;xacro:macro\\&gt;</code> is employed to define templates for the transmission system. Within this, the <code>&lt;transmission&gt;</code> tag is used to specify the type and name of the transmission system, the <code>&lt;joint&gt;</code> tag designates the joint driver interface, and the <code>&lt;actuator&gt;</code> tag specifies mechanical reduction ratios and other related attributes.</p><img loading="lazy" height="366" width="667" src="'+M+'" class="common_img"><p>(2) Define Different Types of Transmission</p><p>Invoke the transmission block <strong>Xacro</strong> macro to define corresponding transmissions for each joint. This allows for the uniform definition of the robot&#39;s transmission system through configuration files.</p><img loading="lazy" height="257" width="641" src="'+N+'" class="common_img"><h2 id="_6-3-gazebo-introduction" tabindex="-1">6.3 Gazebo Introduction <a class="header-anchor" href="#_6-3-gazebo-introduction" aria-label="Permalink to &quot;6.3 Gazebo Introduction&quot;">​</a></h2><p>(1) <strong>Gazebo</strong> is a <strong>3D</strong> dynamic simulator that accurately and effectively simulates robots in complex indoor and outdoor environments. Similar to game engines providing high-fidelity visual simulation, <strong>Gazebo</strong> offers high-fidelity physics simulation. It provides a comprehensive set of sensor models and a user-friendly interaction method for both users and programs.</p><p>(2) Key features of <strong>Gazebo</strong>:</p><p>① Incorporates multiple physics engines</p><p>② Includes a diverse range of robot models and environment libraries</p><p>③ Offers various sensors</p><p>④ Convenient programming and a simple graphical interface</p><p>(3) <strong>Gazebo</strong>&#39;s official recommendation is to run on <strong>Ubuntu</strong> or other <strong>Linux</strong> distributions. Additionally, your computer should have the following capabilities:</p><p>① Dedicated <strong>GPU</strong>: <strong>Nvidia</strong> cards often perform well on <strong>Ubuntu</strong></p><p>② At least an <strong>Intel I5</strong> or equivalent <strong>CPU</strong></p><p>③ Minimum of <strong>500MB</strong> available disk space</p><p>④ Install the highest version of <strong>Ubuntu Trusty</strong> whenever possible</p><h3 id="_6-3-1-gazebo-system-structure" tabindex="-1">6.3.1 <strong>Gazebo</strong> System Structure <a class="header-anchor" href="#_6-3-1-gazebo-system-structure" aria-label="Permalink to &quot;6.3.1 **Gazebo** System Structure&quot;">​</a></h3><p><strong>Gazebo</strong> employs a distributed architecture that encompasses separate libraries for communication, physics simulation, rendering, sensor generation, and the user interface. Additionally, <strong>Gazebo</strong> provides two executable programs for running simulations:</p><p>(1) The server, <code>gzserver</code>, is responsible for simulating physics, rendering, and sensors.</p><p>(2) The client, <code>gzclient</code>, furnishes a graphical interface for visualizing the simulation and interacting with it.</p><p>(3) Communication between the client and server occurs through the <strong>Gazebo</strong> communication library.</p><p><strong>Gazebo</strong>&#39;s <strong>Master</strong> is akin to the master node in the <strong>ROS</strong> system&#39;s communication mechanism but operates with topics. It facilitates topic name discovery and management. A single <strong>Master</strong> can oversee the simulation of multiple physical environments, sensor generation, and graphical interfaces.</p><ul><li><strong>Communication Related Library</strong></li></ul><p>(1) Dependent Libraries: <code>Protobuf</code> and <code>boot::ASIO</code></p><p>(2) External Interface: Supports communication with <strong>Gazebo</strong> nodes through named topics</p><p>(3) Internal Interface: None</p><p>(4) Broadcast Topics: None</p><p>(5) Subscribed Topics: None</p><ul><li><strong>Library for Physics Environment</strong></li></ul><p>(1) This physics environment library provides a simple and fundamental interface for the essential components of simulation, including rigid bodies, collision shapes, and constraints related to joints. This interface is embedded with four open-source physics engines: <strong>Open Dynamics Engine</strong> (<strong>ODE</strong>), <strong>Bullet</strong>, <strong>Simbody</strong>, and <strong>Dynamic Animation and Robotics Toolkit</strong> (<strong>DART</strong>).</p><p>(2) Model descriptions in <strong>XML</strong> format, based on the <strong>SDF</strong> (<strong>Simulation Description Format</strong>), can be loaded by these physics engines. They offer different implementation algorithms and simulation characteristics.</p><p>(3) Dependent Libraries: Dependencies include internal collision detection libraries from dynamic engine libraries.</p><p>(4) External Interface: Provides a simple, general interface for physics simulation.</p><p>(5) Internal Interface: Offers a basic interface defining the physics library for third-party dynamic engines</p><ul><li><strong>Rendering Library</strong></li></ul><p>(1) This parsing library utilizes <strong>OGRE</strong> to provide a simple interface for parsing three-dimensional scenes. It includes simulation of lighting, textures, and the sky, allowing for the creation of plugins for rendering engines.</p><p>(2) Dependent Library: <strong>OGRE</strong></p><p>(3) External Interface: Allows loading, initialization, and scene creation.</p><p>(4) Internal Interface: Stores metadata for visualization and calls the <strong>OGRE</strong> <strong>API</strong> to render models.</p><ul><li><strong>Sensor Data Generation Library</strong></li></ul><p>(1) This sensor library enables various types of sensors to listen to updates from the simulated environment in the physics library. It generates different data based on the characteristics of each sensor.</p><p>(2) Dependent Libraries: Dependencies include the rendering library and the physics environment library.</p><p>(3) External Interface: Provides basic sensor initialization and settings.</p><p>(4) Internal Interface: To be determined (<strong>TBD</strong>).</p><ul><li><strong>GUI</strong></li></ul><p>(1) The <strong>GUI</strong> library uses <strong>QT</strong> to create graphical widgets for user simulation interaction. Users can control the flow of time by pausing or changing the time step through <strong>GUI</strong> widgets. Additionally, users can modify the scene by adding, modifying, or removing models. There are also tools for visualizing and recording simulated sensor data.</p><p>(2) Dependent Libraries: Dependencies include the rendering library and <strong>QT</strong>.</p><p>(3) External Interface: None</p><p>(4) Internal Interface: None</p><h3 id="_6-3-2-coordinate-system" tabindex="-1">6.3.2 Coordinate System <a class="header-anchor" href="#_6-3-2-coordinate-system" aria-label="Permalink to &quot;6.3.2 Coordinate System&quot;">​</a></h3><ul><li><strong>World Coordinate System</strong></li></ul><p>The <strong>World Coordinate System</strong> is a stationary reference coordinate system located on the <strong>&#39;ground.&#39;</strong> It undergoes no translation or rotation changes over time. Of course, here, the term <strong>&#39;ground&#39;</strong> is broadly defined. For example, if the robot is on a tabletop, the world coordinate system would be situated on the plane of that table.</p><img loading="lazy" height="722" width="1577" src="'+V+'" class="common_img"><ul><li><strong>Leg Coordinate System</strong></li></ul><p>The establishment of the joint coordinate system follows the right-hand rule. Therefore, in the example robot model in the diagram below, the red axis represents the <strong>X-axis</strong>, the green axis represents the <strong>Y-axis</strong>, and the blue axis represents the <strong>Z-axis</strong>.</p><p>The number of joint coordinate systems is not fixed and is mainly related to the number of legs. Therefore, extra attention should be paid when establishing joint coordinate systems. <img loading="lazy" height="1040" width="1920" src="'+H+'" class="common_img"></p><ul><li><strong>Introduction to Gazebo GUI</strong></li></ul><p>Enter the following command in the virtual machine terminal to initiate <strong>Gazebo</strong> simulation. Wait for the service to start, and if the content appears as shown in the figure below, it indicates successful <strong>Gazebo</strong> launch.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch pug_description gazebo.launch</span></span></code></pre></div><img loading="lazy" height="592" width="1447" src="'+X+'" class="common_img"><p>Click on the corresponding simulation icon on the desktop to open the simulation tool. The simulation interface is as below:</p><img loading="lazy" height="625" width="1299" src="'+L+'" class="common_img"><p>The function of each section is listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Name</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">Tool bar</td><td style="text-align:center;">Provide the most commonly used options for interaction with simulator</td></tr><tr><td style="text-align:center;">Menu bar</td><td style="text-align:center;">Configure or modify the parameters of the simulation software and some interactive functions</td></tr><tr><td style="text-align:center;">Action bar</td><td style="text-align:center;">Make any operations on the models and modify the parameters</td></tr><tr><td style="text-align:center;">Timestamp</td><td style="text-align:center;">Set the time of the virtual space</td></tr><tr><td style="text-align:center;">Scene</td><td style="text-align:center;">The main part of the simulator where the simulated model is displayed</td></tr></tbody></table><h2 id="_6-4-gazebo-simulation-motion-planning" tabindex="-1">6.4 <strong>Gazebo</strong> Simulation &amp; Motion Planning <a class="header-anchor" href="#_6-4-gazebo-simulation-motion-planning" aria-label="Permalink to &quot;6.4 **Gazebo** Simulation &amp; Motion Planning&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Prior to commencing the simulation, ensure that the robot dog has ample battery power. It is preferable to conduct the simulation when the battery is fully charged.</li><li>The operations outlined below require coordination between the <strong>VM</strong> (<strong>Virtual Machine</strong>) and the robot dog. Please activate the robot dog in advance.</li><li>It is recommended to configure the robot in direct mode for this simulation, in order to fully experience this game.</li></ul></section><h3 id="_6-4-1-install-virtual-machine" tabindex="-1">6.4.1 Install Virtual Machine <a class="header-anchor" href="#_6-4-1-install-virtual-machine" aria-label="Permalink to &quot;6.4.1 Install Virtual Machine&quot;">​</a></h3><p>(1) Install <strong>VMware</strong> virtual machine software which can be found in <a href="./Appendix.html">Appendix -&gt; Virtual Machine &amp; Installation Pack </a>.</p><img loading="lazy" height="103" width="307" src="'+J+'" class="common_img"><p>(2) Open <strong>VMware</strong> software, then click on <strong>File</strong> -&gt; <strong>Open</strong> to open the folder containing virtual machine image.</p><p>(3) Go to the directory where the virtual machine files are stored, select the file, and click the <strong>Open</strong> button to import it.</p><img loading="lazy" height="510" width="849" src="'+W+'" class="common_img"><h3 id="_6-4-2-copy-robot-files-to-the-virtual-machine-and-compile" tabindex="-1">6.4.2 Copy Robot Files to the Virtual Machine and Compile <a class="header-anchor" href="#_6-4-2-copy-robot-files-to-the-virtual-machine-and-compile" aria-label="Permalink to &quot;6.4.2 Copy Robot Files to the Virtual Machine and Compile&quot;">​</a></h3><ul><li><strong>Export Files from the Robot</strong></li></ul><p>(1) Start the robot dog and connect it to the remote control software <strong>NoMachine</strong>.</p><p>(2) Click <img loading="lazy" height="59" width="69" src="'+e+'"> to open the command line terminal. Enter the following command to navigate to the <code>pug/src/</code> directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd pug/src/</span></span></code></pre></div><p>(3) Enter the following command to package the <code>pug_description</code> folder into a zip file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zip -r pug_description.zip pug_description</span></span></code></pre></div><p>(4) Click <img loading="lazy" height="50" width="49" src="'+o+'"> to open the file directory, then navigate to the <code>home/</code> directory.</p><img loading="lazy" height="341" width="1330" src="'+Z+'" class="common_img"><p>(5) Drag the <code>.hiwonderrc</code> file to your computer desktop.</p><img loading="lazy" height="613" width="980" src="'+K+'" class="common_img"><p>(6) Click <img loading="lazy" height="50" width="49" src="'+o+'"> to open the file directory again, then navigate to the <code>home/pug/src</code> directory.</p><img loading="lazy" height="256" width="828" src="'+_+'" class="common_img"><p>(7) Drag the <a href="./Appendix.html">pug_description.zip</a> file to your computer desktop.</p><img loading="lazy" height="614" width="994" src="'+$+'" class="common_img"><ul><li><strong>Export Files to Virtual Machine</strong></li></ul><p>(1) Click on <img loading="lazy" height="48" width="44" src="'+tt+'"> to navigate to the home directory.</p><img loading="lazy" height="280" width="1077" src="'+et+'" class="common_img"><p>(2) Drag and drop the <a href="./Appendix.html">pug_description.zip file</a> from your computer desktop into the virtual machine:</p><img loading="lazy" height="719" width="1145" src="'+ot+'" class="common_img"><ul><li><strong>Create and Compile the Workspace</strong></li></ul><p>(1) In the virtual machine, click <img loading="lazy" height="38" width="48" src="'+i+`"> to open the command line terminal.</p><p>(2) Enter the following command to create the <code>pug/src</code> directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p pug/src</span></span></code></pre></div><p>(3) Unzip <code>pug_description.zip</code> into the current <code>home/pug/src</code> directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unzip pug_description.zip -d pug/src/</span></span></code></pre></div><p>(4) Move the <code>.hiwonderrc</code> file to the <code>ros_ws</code> directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mv .hiwonderrc ros_ws/</span></span></code></pre></div><p>(5) Navigate to the <code>pug</code> directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd pug/</span></span></code></pre></div><p>(6) Enter the following command to compile the workspace:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catkin_make</span></span></code></pre></div><p>(7) If you encounter compilation errors related to missing header files, repeat the compilation process until it completes successfully.</p><p>(8) Edit the <code>.bashrc</code> file by entering the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gedit ~/.bashrc</span></span></code></pre></div><p>(9) Add the following lines to the <code>.bashrc</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source /home/ubuntu/pug/.hiwonderrc</span></span>
<span class="line"><span>source /home/ubuntu/pug/devel/setup.bash</span></span></code></pre></div><p>(10) After editing, save and exit the file using <strong>Ctrl + S</strong> or by clicking the <strong>Save</strong> button in the top right corner.</p><img loading="lazy" height="38" width="898" src="`+it+'" class="common_img"><h3 id="_6-4-3-configure-virtual-machine-network" tabindex="-1">6.4.3 Configure Virtual Machine Network <a class="header-anchor" href="#_6-4-3-configure-virtual-machine-network" aria-label="Permalink to &quot;6.4.3 Configure Virtual Machine Network&quot;">​</a></h3><ul><li><strong>Configure Virtual Machine Network</strong></li></ul><p>(1) Begin by powering up the <strong>ROSPug</strong> robot dog.</p><img loading="lazy" height="157" width="362" src="'+nt+'" class="common_img"><p>(2) After connecting to <strong>VMware</strong> virtual machine, click on <strong>Edit</strong> -&gt; <strong>Virtual Machine Network Configuration</strong>.</p><img loading="lazy" height="153" width="283" src="'+st+'" class="common_img"><p>(3) Click the <strong>&quot;Add Network&quot;</strong> button.</p><img loading="lazy" height="246" width="599" src="'+at+'" class="common_img"><p>(4) Choose the network you want to add (e.g., <strong>&quot;VMnet0&quot;</strong>) and click <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" height="102" width="257" src="'+rt+'" class="common_img"><p>(5) Select the newly added network <strong>&quot;VMnet0&quot;</strong>, set it to <strong>&quot;Bridged&quot;</strong> mode, and set the bridging target to the network card. Click <strong>&quot;OK&quot;</strong> to apply the changes.</p><img loading="lazy" height="529" width="603" src="'+lt+'" class="common_img"><p>(6) Click <strong>&quot;Power on This Virtual Machine&quot;</strong> and wait for the system to boot.</p><img loading="lazy" height="126" width="259" src="'+ct+'" class="common_img"><p>(7) Select the virtual machine, right-click to open the menu, and choose <strong>&quot;Settings&quot;</strong>.</p><img loading="lazy" height="334" width="425" src="'+dt+'" class="common_img"><p>(8) Go to the <strong>&quot;Network Adapter&quot;</strong> section and set the network connection to <strong>&quot;Bridged&quot;</strong> mode.</p><img loading="lazy" height="384" width="737" src="'+gt+'" class="common_img"><ul><li><strong>Configure the Virtual Machine to Publish the Node Address</strong></li></ul><p>(1) Execute the following command to check the <strong>IP</strong> of the virtual machine.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig</span></span></code></pre></div><p>(2) Record the <strong>IP</strong> in the red frame.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the <strong>IP</strong> address does not appear, you need to enter the command <code>sudo dhclient ens33</code> to refresh the <strong>Wi-Fi</strong>.</p></section><img loading="lazy" height="165" width="750" src="'+ht+'" class="common_img"><p>(3) Run the following command to start the virtual machine.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim pug/.hiwonderrc</span></span></code></pre></div><p>(4) Press the <strong>&#39;i&#39;</strong> key to enter edit mode. Update the location shown in the image with the <strong>IP</strong> address of the virtual machine you found earlier. Press <strong>&#39;Esc&#39;</strong>, then type <strong>&#39;:wq&#39;</strong> to save and exit.</p><img loading="lazy" height="73" width="642" src="'+pt+'" class="common_img"><p>(5) Run the following command to update the virtual machine configuration file to activate the settings.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source .bashrc</span></span></code></pre></div><h3 id="_6-4-4-configure-the-robot-dog-s-node-publishing-address" tabindex="-1">6.4.4 Configure the Robot Dog&#39;s Node Publishing Address <a class="header-anchor" href="#_6-4-4-configure-the-robot-dog-s-node-publishing-address" aria-label="Permalink to &quot;6.4.4 Configure the Robot Dog&#39;s Node Publishing Address&quot;">​</a></h3><p>(1) Run the following command to open the virtual machine configuration file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim .hiwonderrc</span></span></code></pre></div><p>(2) Press the <strong>&#39;i&#39;</strong> key to enter edit mode, and set <code>ROS_HOSTNAME</code> to the robot&#39;s <strong>IP</strong> address. Set <code>ROS_MASTER_URI</code> to the virtual machine&#39;s <strong>IP</strong> address. Press <strong>&#39;Esc&#39;</strong>, then type <strong>&#39;:wq&#39;</strong> to save and exit.</p><img loading="lazy" height="64" width="707" src="'+mt+'" class="common_img"><p>(3) Input the command below to update the virtual machine configuration file to validate the settings.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source .bashrc</span></span></code></pre></div><h3 id="_6-4-5-start-simulation" tabindex="-1">6.4.5 Start Simulation <a class="header-anchor" href="#_6-4-5-start-simulation" aria-label="Permalink to &quot;6.4.5 Start Simulation&quot;">​</a></h3><ul><li><strong>Start Gazebo in the Virtual Machine</strong></li></ul><p>(1) Click on <img loading="lazy" height="38" width="48" src="'+i+'"> to initiate the command-line terminal.</p><p>(2) Run the following command to access the virtual machine configuration file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch pug_description gazebo.launch</span></span></code></pre></div><p>(3) Click on the triangle button to start the simulation.</p><img loading="lazy" height="42" width="625" src="'+ut+'" class="common_img"><img loading="lazy" height="926" width="1689" src="'+At+'" class="common_img"><p>(4) If you want to close this game, press <strong>&#39;Ctrl+C&#39;</strong>. If it fails to close the game, please retry.</p><ul><li><strong>Start Simulation Control</strong></li></ul><p>(1) Start the robot dog, and access the robot system desktop using <strong>NoMachine</strong>. Click on <img loading="lazy" height="59" width="69" src="'+e+'"> to initiate the command-line terminal.</p><p>(2) Run the following command to start the game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch pug_description sim_base.launch</span></span></code></pre></div><p>(3) Activate the wireless handle to control the robot to move.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Button</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Restore to Initial Pose</td></tr><tr><td style="text-align:center;">↑</td><td style="text-align:center;">Move Forward</td></tr><tr><td style="text-align:center;">↓</td><td style="text-align:center;">Move Backward</td></tr><tr><td style="text-align:center;">←</td><td style="text-align:center;">Turn Left</td></tr><tr><td style="text-align:center;">→</td><td style="text-align:center;">Turn Right</td></tr><tr><td style="text-align:center;">△</td><td style="text-align:center;">Raise Body Height</td></tr><tr><td style="text-align:center;">×</td><td style="text-align:center;">Lower Body Height</td></tr><tr><td style="text-align:center;">◻</td><td style="text-align:center;">Move Left</td></tr><tr><td style="text-align:center;">○</td><td style="text-align:center;">Move Right</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Tilt Body Upward</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">Tilt Body Downward</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Twist Body Left</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">Twist Body Right</td></tr><tr><td style="text-align:center;">Left joystick</td><td style="text-align:center;">Control the robot to go forward, backward, translate left and right</td></tr><tr><td style="text-align:center;">Right joystick</td><td style="text-align:center;">Turn left and right</td></tr></tbody></table><p>(4) If you want to terminate this game, press <strong>&#39;Ctrl+C&#39;</strong>. If it fails to close the game, please retry.</p>',296)])])}const It=n(ft,[["render",yt]]);export{Ct as __pageData,It as default};
